:root {
	--ge-panel-color: #f1f3f4;
	--toolbar-color: #f1f3f4;
	--workspace-color: #ececec;
	--dark-toolbar-color: #1e2022;
	--inactive-color: #e4e4e4;
	--active-color: #c4c4c4;
	--primary-color: #c2e7ff;
	--primary-hover-color: #abcfe7;
	--accent-color: #e1e9f7;
	--accent-hover-color: #d8e5f8;
	--accent-text-color: #0b57d0;
	--border-color: #dadada;
	--highlight-color: #e2e2e2;
	--scrollbar-hover-color: #959798;
	--text-color: #3F3F3F;
	--dark-color: #121212;
	--ge-dark-panel-color: #1B1D1E;
	--dark-border-color: #333333;
	--dark-text-color: #C0C0C0;
	--dark-accent-color: #003555;
	--dark-accent-text-color: #52a5f6;
	--dark-active-accent-color: #004A77;
	--dark-inverse-active-color: #c4c4c4;
	--dark-highlight-color: #000000;
	--dark-header-color: #1B1D1E;
	/* Dialogs, windows and comments */
	--dialog-color: #f0f0f0;
	--dark-dialog-color: #2a2a2a;
	--strong-text-color: #1d1d1f;
	--dark-strong-text-color: #e5e5e7;
	--secondary-text-color: #6e6e73;
	--dark-secondary-text-color: #a0a0a0;
	--faint-text-color: #8e8e93;
	--dark-faint-text-color: #7a7a7e;
	/* Input fields, cards and chips */
	--field-color: #ffffff;
	--dark-field-color: #1c1c1e;
	--field-border-color: #d2d2d7;
	--dark-field-border-color: #48484a;
	--strong-border-color: #b9b9be;
	--dark-strong-border-color: #5a5a5e;
	--card-color: #ffffff;
	--dark-card-color: #2c2c2e;
	--soft-color: whitesmoke;
	--dark-soft-color: #3a3a3c;
	--soft-hover-color: #f0f0f2;
	--dark-soft-hover-color: #3a3a3c;
	/* Accents (selected and focused states) */
	--focus-color: #0071e3;
	--dark-focus-color: #0a84ff;
	--mention-color: #0a4bb0;
	--dark-mention-color: #7eb1ff;
	--mention-background-color: #e8f0fe;
	--dark-mention-background-color: #10325f;
	--selected-color: #d4e4f7;
	--selected-hover-color: #c4d8f0;
	--active-item-color: lightgray;
	--dark-active-item-color: darkgray;
	/* Status */
	--error-color: #b62623;
	--dark-error-color: #ffffff;
	--error-background-color: #eacccc;
	--dark-error-background-color: #a20025;
	/* Misc */
	--scrollbar-color: #e2e2e2;
	--dark-scrollbar-color: #2c2c2c;
	--prop-stripe-color: #fcfcfc;
	--prop-accent-color: #D9E1F2;
	--prop-accent-text-color: #305496;
}

.geEditor {
	font-family: -apple-system, BlinkMacSystemFont, "Segoe UI Variable", "Segoe UI", system-ui, ui-sans-serif, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
	color-scheme: light dark;
	position: absolute;
	overflow: hidden;
	font-size: 14px;
	width: 100%;
	height: 100%;
	margin: 0;
	display: grid;
	grid-template-rows: min-content min-content 1fr min-content;
	grid-template-columns: min-content min-content 1fr min-content;
}

.gePrimaryBtn {
	background-color: light-dark(var(--primary-color), var(--dark-accent-color));
	box-shadow: none;
	border: none;
}

div.geActivePage {
	background-color: light-dark(var(--accent-color), var(--dark-accent-color));
	color: light-dark(var(--accent-text-color), var(--dark-accent-text-color));
}

html body.geEditor .gePrimaryBtn:hover:not([disabled]) {
	background-color: light-dark(var(--primary-hover-color), var(--dark-active-accent-color));
	box-shadow: none;
	border: none;
}

.geTabItem.geTabZoom {
	position: absolute;
	display: flex;
	align-items: center;
	justify-content: center;
	padding-right: 16px;
	width: 50px;
	right: 0px;
	bottom: 0px;
	box-sizing: content-box;
	background-position: right 6px center;
	background-repeat: no-repeat;
	background-size: 13px;
	z-index: 1;
	cursor: pointer;
}

html body div.mxPopupMenu {
	border-radius: 5px;
	border: 1px solid #c0c0c0;
	padding: 5px 0 5px 0;
	box-shadow: 0px 4px 17px -4px rgba(96, 96, 96, 1);
}

html table.mxPopupMenu td.mxPopupMenuItem {
	font-size: 14px;
	padding-top: 4px;
	padding-bottom: 4px;
}

html tr.mxPopupMenuItem,
html td.mxPopupMenuItem {
	transition-property: none !important;
}

html body.geDarkMode.geEditor div.mxPopupMenu {
	border: 1px solid var(--dark-border-color);
	background-color: var(--ge-dark-panel-color);
}

html body.geDarkMode.geEditor div.mxPopupMenu hr {
	background-color: var(--dark-border-color);
}

.geBtn.geGenerateDiagramButton {
	position: absolute;
	bottom: 0px;
	right: 0px;
	left: 0px;
	margin: 8px;
}

.geEditor .geTemplate .geButton.geRoundButton {
	position: absolute;
	background: white;
	margin: 0;
	padding: 2px;
	opacity: 1 !important;
	width: 16px;
	height: 16px;
	right: 0px;
	top: 0px;
}

html body.geDarkMode.geEditor table.mxPopupMenu tr.mxPopupMenuItemHover {
	background-color: var(--dark-highlight-color);
}

html body.geDarkMode table.mxPopupMenu hr {
	border-color: var(--dark-border-color);
	background-color: var(--dark-color);
}

html body.geDarkMode .geDialog,
html body.geDarkMode div.mxWindow,
html body div.mxWindow.geDarkMode {
	background-color: var(--dark-dialog-color);
	border-color: #838383;
	box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), 0 2px 8px rgba(0, 0, 0, 0.3);
}

.geDialog,
html div.mxWindow,
.geSketch .geToolbarContainer:not(.geDialog *, .mxWindow *) {
	border-radius: 12px;
	box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12), 0 2px 8px rgba(0, 0, 0, 0.08);
}

.geButtonContainer .gePrimaryBtn .geButton {
	background-position: left center;
	padding: 0 2px 0 24px;
	width: auto;
}

html body div.geBtn.geSmallBanner {
	border-radius: 20px;
	font-size: inherit;
	padding: 6px 12px 6px 20px;
	display: flex;
	height: auto;
	bottom: 4px;
}

.geBtn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	font-size: 14px;
	font-weight: 550;
	height: 30px;
	margin: 0 0 0 8px;
	min-width: 72px;
	outline: 0;
	padding: 0 8px;
	text-overflow: ellipsis;
	white-space: nowrap;
	overflow: hidden;
}

.geBtn.geBanner {
	display: block;
	position: absolute;
	bottom: 10px;
	left: 50%;
	max-width: 90%;
	white-space: nowrap;
	cursor: pointer;
	font-size: 16px;
	padding: 18px 34px 30px 20px;
	font-weight: bold;
	transform: translate(-50%, 0%);
	transition: 1000ms;
	box-shadow: rgb(221, 221, 221) 1px 1px 2px 0px;
}

td.mxPopupMenuIcon .geStyleMenuItem>div {
	background-position: bottom left;
	background-repeat: repeat-x;
	border-color: black;
	border-width: 1px;
	margin: 8px 0;
	height: 1px;
	width: 100%;
}

.geButton.gePageMenu>span {
	padding: 0px;
	max-width: 160px;
	overflow: hidden;
	text-overflow: ellipsis;
}

.geButton.geZoomInput {
    cursor: initial;
    font-size: 14px;
    border-style: none;
    border-color: #000000;
    padding: 0px 16px 0px 2px;
    background-position: right 2px center;
    text-align: center;
    height: 28px;
    width: 62px;
}

button:hover:not([disabled], .geBigButton, .geShareBtn),
select:hover:not([disabled]),
.geColorBtn:hover:not([disabled]),
.geStyleBtn:hover:not([disabled]),
table.mxPopupMenu tr.mxPopupMenuItemHover {
	background-color: light-dark(var(--highlight-color), var(--dark-border-color));
}

.geButton>div:not(.geShortcutKey) {
	display: flex;
	align-items: center;
	width: 100%;
	height: 100%;
	background-position: left 2px center;
	background-repeat: no-repeat;
	background-size: 18px;
}

.geButton,
.geTitle,
.geItem {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	background-position: center center;
	background-repeat: no-repeat;
	background-size: 18px;
	white-space: nowrap;
	z-index: 1;
	padding: 2px;
}

.geButton,
.geTitle {
	color: black;
	border-radius: 6px;
	box-sizing: border-box;
	margin: 2px;
}

.geButton.geRoundButton:not(.geEmbed.geCompactMode .geButtonContainer .geButton) {
	background-size: 24px 24px;
	justify-content: center;
	box-sizing: content-box;
	border-radius: 50%;
	padding: 6px;
}

.geButton.geRoundButton > .geUserAvatar {
	width: 26px;
	height: 26px;
	border-radius: 50%;
	background-position: center center;
	background-repeat: no-repeat;
	/* Scale the SVG silhouette to fill the box like the original <img> did
	   (.geRoundButton img { width: 26px }); without this it falls back to the
	   image's intrinsic 24px and renders too small. See #5364. */
	background-size: contain;
}

.geTabContainer {
	box-sizing: border-box;
	white-space: nowrap;
	overflow: hidden;
	padding: 0 20px 0 12px;
	display: flex;
	height: 32px;
	z-index: 1;
}

.geTabScroller {
	display: inline-block;
	position: relative;
	white-space: nowrap;
	overflow: hidden;
	overflow-x: auto;
	margin: 0 8px;
	-ms-overflow-style: none;
	scrollbar-width: none;
	left: 0px;
}

.geTab {
	height: 100%;
	box-sizing: border-box;
	text-overflow: ellipsis;
	font-size: 13px;
	display: inline-flex;
	align-items: center;
	cursor: move;
}

.geSidebarTooltip .geButton {
	position: absolute;
	padding: 2px;
	margin: 0;
	right: 2px;
	top: 2px;
	width: 20px;
	height: 20px;
}

.geDialog {
	position: absolute;
	background-color: light-dark(var(--dialog-color), var(--dark-dialog-color));
	line-height: 1em;
	overflow: hidden;
	padding: 24px;
	border: light-dark(none, 1px solid rgba(255, 255, 255, 0.1));
	left: 50%;
	top: 50%;
	max-height: 100%;
	max-width: 100%;
	transform: translate(-50%, -50%);
	box-sizing: border-box;
}

.geDialog > .geButton {
	top: 8px !important;
	right: 8px !important;
	width: 20px;
	height: 20px;
	border-radius: 50%;
	background-size: 10px;
	background-position: center;
	background-repeat: no-repeat;
	opacity: 0.5;
	transition: opacity 0.1s ease, background-color 0.1s ease;
}

.geDialog input[type="text"],
.geDialog input[type="number"],
.geDialog textarea,
.geDialog select {
	border-radius: 6px;
	border: light-dark(1px solid rgba(0, 0, 0, 0.15), 1px solid rgba(255, 255, 255, 0.15));
	background-color: light-dark(var(--field-color), var(--dark-field-color));
	padding: 4px 8px;
	font-size: 13px;
	outline: none;
	transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.geDialog input[type="text"]:focus,
.geDialog input[type="number"]:focus,
.geDialog textarea:focus,
.geDialog select:focus {
	border-color: light-dark(var(--focus-color), var(--dark-focus-color));
	box-shadow: 0 0 0 3px light-dark(color-mix(in srgb, var(--focus-color) 25%, transparent), color-mix(in srgb, var(--dark-focus-color) 25%, transparent));
}

.geDialog h3 {
	width: 100%;
	text-align: center;
	margin: 0 0 16px;
	flex-shrink: 0;
}

.geDialog.geInlineDialog {
	padding: 0px;
	left: auto;
	transform: none;
	z-index: 4;
}

.geEditor div.mxPopupMenu {
	box-shadow: 0px 0px 2px #C0C0C0;
	background-color: var(--ge-panel-color);
	background-image: none;
	border-radius: 4px;
	border-style: solid;
	border-width: 1px;
	border-color: lightgray;
	padding: 3px;
}

.geEditor div.mxPopupMenu.geToolbarMenu {
	border-radius: 10px;
	box-shadow: 0px 0px 3px 1px #d1d1d1;
	padding: 10px 14px 12px 14px;
	background-color: light-dark(var(--ge-panel-color), var(--ge-dark-panel-color));
}

table.mxPopupMenu hr {
	color: light-dark(var(--border-color), var(--dark-border-color));
	background-color: light-dark(var(--border-color), var(--dark-border-color));
	border: none;
	height: 1px;
}

.geActivePage {
	background-color: light-dark(#ffffff, #000000) !important;
	color: inherit !important;
	filter: invert(1);
}

.geDialog {
	background-color: light-dark(#ffffff, var(--ge-dark-panel-color)) !important;
	border: 1px solid light-dark(#000000, #FFFFFF) !important;
	box-shadow: none !important;
}

html body.geDarkMode .geDialog,
html body.geDarkMode div.mxWindow,
html body div.mxWindow.geDarkMode {
	background-color: var(--ge-dark-panel-color) !important;
	border-color: #FFFFFF !important;
	box-shadow: none !important;
}

.geDialog input[type="text"],
.geDialog input[type="number"],
.geDialog textarea,
.geDialog select {
	border: 1px solid light-dark(#000000, #FFFFFF) !important;
	background-color: light-dark(#ffffff, #000000) !important;
}

div.mxPopupMenu {
	-webkit-box-shadow: 3px 3px 12px #C0C0C0;
	-moz-box-shadow: 3px 3px 12px #C0C0C0;
	box-shadow: 3px 3px 12px #C0C0C0;
	background: url(data:image/gif;base64,R0lGODlhGgAUAIAAAOzs7PDw8CH5BAAAAAAALAAAAAAaABQAAAIijI+py70Ao5y02lud3lzhD4ZUR5aPiKajyZbqq7YyB9dhAQA7);
	position: absolute;
	border-style: solid;
	border-width: 1px;
	border-color: black;
}

td.mxPopupMenuItem {
	padding: 2px 30px 2px 10px;
	white-space: nowrap;
	font-family: Arial;
	font-size: 8pt;
}

